import 'dart:convert';

// WordPronunciation represents a word's pronunciation data fetched from Supabase
class WordPronunciation {
  final String word;
  final String? fullWordUrl;
  final String? breakdownUrl;
  final List<String> syllables;
  final List<BreakdownSegment> breakdownSegments;
  final bool includesBreakdown;

  const WordPronunciation({
    required this.word,
    this.fullWordUrl,
    this.breakdownUrl,
    required this.syllables,
    required this.breakdownSegments,
    required this.includesBreakdown,
  });

  // fromRow: Construct from a raw Supabase database row (Map)
  factory WordPronunciation.fromRow(Map<String, dynamic> row) {
    final rawSegments = row['breakdown_segments'];
    List<BreakdownSegment> segments = [];
    if (rawSegments != null) {
      final List<dynamic> decoded =
          rawSegments is String ? jsonDecode(rawSegments) : rawSegments;
      segments = decoded
          .map((s) => BreakdownSegment.fromMap(s as Map<String, dynamic>))
          .toList();
    }

    final rawSyllables = row['syllables'];
    List<String> syllableList = [];
    if (rawSyllables != null) {
      if (rawSyllables is List) {
        syllableList = List<String>.from(rawSyllables);
      } else if (rawSyllables is String) {
        syllableList = List<String>.from(jsonDecode(rawSyllables));
      }
    }

    return WordPronunciation(
      word: row['word'] as String,
      fullWordUrl: row['full_word_url'] as String?,
      breakdownUrl: row['breakdown_url'] as String?,
      syllables: syllableList,
      breakdownSegments: segments,
      includesBreakdown: row['includes_breakdown'] as bool? ?? false,
    );
  }

  bool get hasAudio => fullWordUrl != null || breakdownUrl != null;
}

// BreakdownSegment represents one phonetic/syllable segment in a word breakdown
class BreakdownSegment {
  final int index;
  final String chunk;
  final String spoken;
  final int startMs;
  final int endMs;

  const BreakdownSegment({
    required this.index,
    required this.chunk,
    required this.spoken,
    required this.startMs,
    required this.endMs,
  });

  factory BreakdownSegment.fromMap(Map<String, dynamic> map) {
    return BreakdownSegment(
      index: map['index'] as int,
      chunk: map['chunk'] as String,
      spoken: map['spoken'] as String,
      startMs: map['startMs'] as int,
      endMs: map['endMs'] as int,
    );
  }
}

// BookPronunciationManifest: word -> pronunciation data for an entire book
typedef BookPronunciationManifest = Map<String, WordPronunciation>;

