import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../../data/pronunciation_models.dart';
import '../../../../data/pronunciation_repository.dart';
import '../services/pronunciation_playback_service.dart';
import '../../pronunciation_highlight.dart';

// WordTtsState holds all TTS-related state for the reader
class WordTtsState {
  final int? tappedWordIndex;
  final List<PronunciationHighlightPart>? highlightParts;
  final int? activeHighlightPartIndex;

  const WordTtsState({
    this.tappedWordIndex,
    this.highlightParts,
    this.activeHighlightPartIndex,
  });

  WordTtsState copyWith({
    Object? tappedWordIndex = _sentinel,
    Object? highlightParts = _sentinel,
    Object? activeHighlightPartIndex = _sentinel,
  }) {
    return WordTtsState(
      tappedWordIndex: tappedWordIndex == _sentinel
          ? this.tappedWordIndex
          : tappedWordIndex as int?,
      highlightParts: highlightParts == _sentinel
          ? this.highlightParts
          : highlightParts as List<PronunciationHighlightPart>?,
      activeHighlightPartIndex: activeHighlightPartIndex == _sentinel
          ? this.activeHighlightPartIndex
          : activeHighlightPartIndex as int?,
    );
  }

  static const _sentinel = Object();
}

// WordTtsNotifier manages word-level TTS state
class WordTtsNotifier extends AsyncNotifier<WordTtsState> {
  late PronunciationPlaybackService _playbackService;

  @override
  Future<WordTtsState> build() async {
    return const WordTtsState();
  }

  void initialize(PronunciationPlaybackService service) {
    _playbackService = service;
    _playbackService.highlightPartsStream.listen((parts) {
      final current = state.valueOrNull ?? const WordTtsState();
      state = AsyncData(current.copyWith(highlightParts: parts));
    });
    _playbackService.activePartIndexStream.listen((index) {
      final current = state.valueOrNull ?? const WordTtsState();
      state = AsyncData(current.copyWith(activeHighlightPartIndex: index));
    });
    _playbackService.playbackCompleteStream.listen((_) {
      final current = state.valueOrNull ?? const WordTtsState();
      state = AsyncData(current.copyWith(tappedWordIndex: null));
    });
  }

  Future<void> onWordTapped(
    int wordIndex,
    String word,
    PronunciationRepository repository,
    String bookId,
  ) async {
    final current = state.valueOrNull ?? const WordTtsState();
    state = AsyncData(current.copyWith(tappedWordIndex: wordIndex));
    await _playbackService.playWord(word, repository, bookId);
  }
}

// Provider
final wordTtsProvider =
    AsyncNotifierProvider<WordTtsNotifier, WordTtsState>(WordTtsNotifier.new);

