// PronunciationHighlightPart represents one syllable/segment in the highlight strip
class PronunciationHighlightPart {
  final String label;
  final int segmentIndex;

  const PronunciationHighlightPart({
    required this.label,
    required this.segmentIndex,
  });

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PronunciationHighlightPart &&
          runtimeType == other.runtimeType &&
          label == other.label &&
          segmentIndex == other.segmentIndex;

  @override
  int get hashCode => label.hashCode ^ segmentIndex.hashCode;
}

