void main() {
  group('WordTtsNotifier', () {
    test('initial state is empty WordTtsState', () async {
      final container = ProviderContainer();
      addTearDown(container.dispose);

      final state = await container.read(wordTtsProvider.future);
      expect(state.tappedWordIndex, isNull);
      expect(state.highlightParts, isNull);
      expect(state.activeHighlightPartIndex, isNull);
    });

    test('onWordTapped sets tappedWordIndex', () async {
      final positionController = StreamController<Duration>.broadcast();
      addTearDown(positionController.close);

      final pronunciation = WordPronunciation(
        word: 'hello',
        fullWordUrl: 'https://example.com/hello.mp3',
        breakdownUrl: null,
        syllables: ['hel', 'lo'],
        breakdownSegments: [],
        includesBreakdown: false,
      );

      final repository = _FakePronunciationRepository({'hello': pronunciation});

      final service = PronunciationPlaybackService(
        pronunciationPosition: positionController.stream,
        playAudio: (url) async {},
        playBreakdown: (url) async {},
      );

      final container = ProviderContainer();
      addTearDown(container.dispose);

      final notifier = container.read(wordTtsProvider.notifier);
      notifier.initialize(service);

      await notifier.onWordTapped(0, 'hello', repository, 'book1');

      final state = container.read(wordTtsProvider).valueOrNull;
      expect(state?.tappedWordIndex, isNull); // cleared after playback
    });

    test('onWordTapped builds highlightParts for word with breakdown', () async {
      final positionController = StreamController<Duration>.broadcast();
      addTearDown(positionController.close);

      final pronunciation = WordPronunciation(
        word: 'butterfly',
        fullWordUrl: 'https://example.com/butterfly_full.mp3',
        breakdownUrl: 'https://example.com/butterfly_breakdown.mp3',
        syllables: ['but', 'ter', 'fly'],
        breakdownSegments: [
          BreakdownSegment(
              index: 0, chunk: 'but', spoken: 'but', startMs: 0, endMs: 300),
          BreakdownSegment(
              index: 1, chunk: 'ter', spoken: 'ter', startMs: 300, endMs: 600),
          BreakdownSegment(
              index: 2, chunk: 'fly', spoken: 'fly', startMs: 600, endMs: 900),
        ],
        includesBreakdown: true,
      );

      final repository =
          _FakePronunciationRepository({'butterfly': pronunciation});

      final service = PronunciationPlaybackService(
        pronunciationPosition: positionController.stream,
        playAudio: (url) async {},
        playBreakdown: (url) async {},
      );

      final container = ProviderContainer();
      addTearDown(container.dispose);

      final notifier = container.read(wordTtsProvider.notifier);
      notifier.initialize(service);

      // Capture highlight parts events
      final List<List<PronunciationHighlightPart>?> capturedParts = [];
      container.listen<AsyncValue<WordTtsState>>(wordTtsProvider, (prev, next) {
        final parts = next.valueOrNull?.highlightParts;
        if (parts != null) capturedParts.add(parts);
      });

      await notifier.onWordTapped(1, 'butterfly', repository, 'book1');

      expect(capturedParts, isNotEmpty);
      expect(capturedParts.first?.length, 3);
      expect(capturedParts.first?.first.label, 'but');
    });

    test('activeHighlightPartIndex advances with position stream', () async {
      final positionController = StreamController<Duration>.broadcast();
      addTearDown(positionController.close);

      final pronunciation = WordPronunciation(
        word: 'butterfly',
        fullWordUrl: 'https://example.com/butterfly_full.mp3',
        breakdownUrl: 'https://example.com/butterfly_breakdown.mp3',
        syllables: ['but', 'ter', 'fly'],
        breakdownSegments: [
