      final repository =
          _FakePronunciationRepository({'butterfly': pronunciation});

      final List<int?> capturedIndexes = [];
      final service = PronunciationPlaybackService(
        pronunciationPosition: positionController.stream,
        playAudio: (url) async {},
        playBreakdown: (url) async {
          // Simulate position events during breakdown playback
          positionController.add(const Duration(milliseconds: 0));
          positionController.add(const Duration(milliseconds: 350));
          positionController.add(const Duration(milliseconds: 700));
        },
      );

      final container = ProviderContainer();
      addTearDown(container.dispose);

      final notifier = container.read(wordTtsProvider.notifier);
      notifier.initialize(service);

      container.listen<AsyncValue<WordTtsState>>(wordTtsProvider, (prev, next) {
        final index = next.valueOrNull?.activeHighlightPartIndex;
        capturedIndexes.add(index);
      });

      await notifier.onWordTapped(1, 'butterfly', repository, 'book1');

      // Should have advanced through segments
      expect(capturedIndexes, contains(1));
      expect(capturedIndexes, contains(2));
    });
  });
