import '../config/app_config.dart';

/// Transport abstraction so tests can inject a fake.
abstract class AnalyticsTransport {
  Future<int> postEvent(Uri url, Map<String, String> headers, String body);
}

class HttpAnalyticsTransport implements AnalyticsTransport {
  HttpAnalyticsTransport(this._client);

  final http.Client _client;

  @override
  Future<int> postEvent(Uri url, Map<String, String> headers, String body) async {
    final response = await _client.post(url, headers: headers, body: body);
    return response.statusCode;
  }
}

/// Repository for emitting analytics events to the backend.
///
/// Events are buffered in-memory and flushed in the background. Calls to
/// [track] / [trackEvent] return `true` when the event was successfully
/// queued (NOT when delivery succeeded). Delivery happens asynchronously
/// with retry-with-backoff. Analytics is non-fatal: this class never
/// throws to callers and never blocks UI flows on the network.
class AnalyticsRepository {
  AnalyticsRepository({
    AnalyticsTransport? transport,
    http.Client? httpClient,
    int maxBufferSize = 200,
    int flushBatchSize = 20,
    Duration flushInterval = const Duration(seconds: 5),
    int maxRetries = 3,
    Duration retryBaseDelay = const Duration(milliseconds: 500),
    Duration retryMaxDelay = const Duration(seconds: 5),
    Future<void> Function(Duration)? sleep,
  })  : _transport = transport ??
            HttpAnalyticsTransport(httpClient ?? http.Client()),
        _maxBufferSize = maxBufferSize,
        _flushBatchSize = flushBatchSize,
        _flushInterval = flushInterval,
        _maxRetries = maxRetries,
        _retryBaseDelay = retryBaseDelay,
        _retryMaxDelay = retryMaxDelay,
        _sleep = sleep ?? Future.delayed;

  final AnalyticsTransport _transport;
  final int _maxBufferSize;
  final int _flushBatchSize;
  final Duration _flushInterval;
  final int _maxRetries;
  final Duration _retryBaseDelay;
  final Duration _retryMaxDelay;
  final Future<void> Function(Duration) _sleep;

  final Queue<_QueuedEvent> _buffer = Queue<_QueuedEvent>();
  Timer? _flushTimer;
  bool _draining = false;
  bool _disposed = false;

  /// Emit an analytics event. Returns `true` if the event was successfully
  /// buffered for delivery (not whether the network POST succeeded).
  Future<bool> track(
    String eventType, {
    String? userId,
    String? sessionId,
    Map<String, dynamic>? metadata,
  }) async {
    if (_disposed) {
      return false;
    }

    final payload = <String, dynamic>{
      'event_type': eventType,
      'event_data': <String, dynamic>{
        if (sessionId != null) 'session_id': sessionId,
        if (metadata != null) ...metadata,
      },
      if (userId != null) 'user_id': userId,
      if (sessionId != null) 'session_id': sessionId,
      'created_at': DateTime.now().toUtc().toIso8601String(),
    };

    return _enqueue(payload);
  }

  /// Direct event emission for cases where the caller already has a payload
  /// shaped for the backend. Returns `true` if queued (not delivered).
  Future<bool> trackEvent(Map<String, dynamic> event) async {
    if (_disposed) {
      return false;
    }
    final payload = Map<String, dynamic>.from(event);
    payload.putIfAbsent(
      'created_at',
      () => DateTime.now().toUtc().toIso8601String(),
    );
    return _enqueue(payload);
  }

  bool _enqueue(Map<String, dynamic> payload) {
    if (_buffer.length >= _maxBufferSize) {
      // Drop oldest to bound memory. Never throw to caller.
      final dropped = _buffer.removeFirst();
      debugPrint(
        'AnalyticsRepository: buffer overflow, dropped oldest event '
        '(${dropped.payload['event_type']})',
      );
    }
    _buffer.add(_QueuedEvent(payload: payload));

    if (_buffer.length >= _flushBatchSize) {
      // Fire-and-forget — flush errors must not propagate.
      unawaited(_drain());
    } else {
      _ensureFlushTimer();
    }
    return true;
  }

  void _ensureFlushTimer() {
    if (_flushTimer != null && _flushTimer!.isActive) {
      return;
    }
    _flushTimer = Timer(_flushInterval, () {
      unawaited(_drain());
    });
  }

  void _cancelFlushTimer() {
    _flushTimer?.cancel();
    _flushTimer = null;
  }

  /// Force a flush of any buffered events. Safe to call from app lifecycle
  /// hooks (paused/detached). Awaits the in-flight drain.
  Future<void> flush() async {
    await _drain();
  }

  /// Caller-visible hook for app lifecycle changes. Apps should invoke this
  /// when going to background / detached so events are not lost.
  Future<void> onAppLifecyclePaused() => flush();

  Future<void> _drain() async {
    if (_disposed) return;
    if (_draining) return;
    _draining = true;
    _cancelFlushTimer();

    try {
      // TODO(analytics): when /api/analytics/events/batch lands, send the
      // whole buffer in one POST instead of serializing one-at-a-time.
      while (_buffer.isNotEmpty && !_disposed) {
        final event = _buffer.first;
        final outcome = await _sendWithRetry(event);
        if (outcome == _SendOutcome.dropped ||
            outcome == _SendOutcome.delivered) {
          // Either delivered or permanently dropped; remove from head.
          if (_buffer.isNotEmpty && identical(_buffer.first, event)) {
            _buffer.removeFirst();
          }
        } else {
          // Transport gave up after retries; drop to avoid unbounded growth.
          if (_buffer.isNotEmpty && identical(_buffer.first, event)) {
            _buffer.removeFirst();
          }
        }
      }
    } finally {
      _draining = false;
      if (_buffer.isNotEmpty) {
        _ensureFlushTimer();
      }
    }
  }

  Future<_SendOutcome> _sendWithRetry(_QueuedEvent event) async {
    final url = Uri.parse('${AppConfig.apiBaseUrl}/api/analytics/events');
    final headers = const {'Content-Type': 'application/json'};
    final body = jsonEncode(event.payload);

    var attempt = 0;
    while (true) {
      try {
        final status = await _transport.postEvent(url, headers, body);
        if (status >= 200 && status < 300) {
          return _SendOutcome.delivered;
        }
        if (status >= 400 && status < 500) {
          // Payload bug — do not retry.
          debugPrint(
            'AnalyticsRepository: dropping event after $status from server '
            '(${event.payload['event_type']})',
          );
          return _SendOutcome.dropped;
        }
        // 5xx: treat as transient.
      } on SocketException catch (e) {
        debugPrint('AnalyticsRepository: socket error: $e');
      } on http.ClientException catch (e) {
        debugPrint('AnalyticsRepository: http client error: $e');
      } on TimeoutException catch (e) {
        debugPrint('AnalyticsRepository: timeout: $e');
      } catch (e) {
        // Unknown transport error — treat transient but log.
        debugPrint('AnalyticsRepository: unexpected transport error: $e');
      }

      attempt += 1;
      if (attempt > _maxRetries) {
        debugPrint(
          'AnalyticsRepository: giving up after $_maxRetries retries '
          '(${event.payload['event_type']})',
        );
        return _SendOutcome.exhausted;
      }
      await _sleep(_backoffDelay(attempt));
    }
  }

  Duration _backoffDelay(int attempt) {
    // attempt is 1-indexed for the wait *before* the next try.
    final exponent = math.min(attempt - 1, 10);
    final ms = _retryBaseDelay.inMilliseconds * (1 << exponent);
    final capped = math.min(ms, _retryMaxDelay.inMilliseconds);
    return Duration(milliseconds: capped);
  }

  /// Visible for tests.
  @visibleForTesting
  int get bufferLength => _buffer.length;

  Future<void> dispose() async {
    _disposed = true;
    _cancelFlushTimer();
  }
}

class _QueuedEvent {
  _QueuedEvent({required this.payload});
  final Map<String, dynamic> payload;
}

enum _SendOutcome { delivered, dropped, exhausted }
